package com.tickethub.booking.controller;
import com.tickethub.booking.dto.request.*; import com.tickethub.booking.dto.response.*; import com.tickethub.booking.security.JwtAuthenticationFilter.JwtPrincipal; import com.tickethub.booking.service.BookingService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/bookings") @Tag(name = "Bookings", description = "Customer booking APIs") public class BookingController { private final BookingService service; public BookingController(BookingService s){service=s;}
 @Operation(summary = "Create a booking") @PostMapping public ResponseEntity<CreateBookingResponse> create(@Valid @RequestBody CreateBookingRequest r,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){JwtPrincipal p=(JwtPrincipal)auth.getPrincipal();return ResponseEntity.status(201).body(service.create(r,key,Long.valueOf(p.userId()),p.email()));}
 @Operation(summary = "Get a booking") @GetMapping("/{id}") public BookingResponse get(@PathVariable("id") Long id,Authentication auth){JwtPrincipal p=(JwtPrincipal)auth.getPrincipal();return service.get(id,Long.valueOf(p.userId()));}
 @Operation(summary = "Cancel a booking") @PostMapping("/{id}/cancel") @ResponseStatus(HttpStatus.NO_CONTENT) public void cancel(@PathVariable("id") Long id,Authentication auth){JwtPrincipal p=(JwtPrincipal)auth.getPrincipal();service.cancel(id,Long.valueOf(p.userId()));}
 @Operation(summary = "Get booking Saga state") @GetMapping("/{id}/saga") public java.util.Map<String, Object> getSagaState(@PathVariable("id") Long id, Authentication auth){JwtPrincipal p=(JwtPrincipal)auth.getPrincipal(); return service.getSagaState(id, Long.valueOf(p.userId()));}
}
